UPDATE paper_question SET answer='B', analysis='从创新与环境关系来看，可以把创新分为： - 消极防御型创新； - 积极攻击型创新。 因此选 B。 --- ## 二、多项选择题' WHERE id=4418 AND deleted=0;
UPDATE paper_question SET answer='ABCD', analysis='明茨伯格的决策角色包括： - 企业家； - 冲突管理者； - 资源分配者； - 谈判者。 因此四项全选。 ---' WHERE id=4419 AND deleted=0;
UPDATE paper_question SET answer='ABC', analysis='学习型组织强调： - 创新是组织中每个人的事情； - 管理者的重要职责是调动、授权员工； - 关注“不学习、不变革”的风险。 “产品和服务是组织的竞争优势”不是学习型组织的典型定义特征。 因此选 ABC。 ---' WHERE id=4420 AND deleted=0;
UPDATE paper_question SET answer='BC', analysis='定量决策方法通常建立在数学模型、数据和数量分析基础上。 - 量本利分析法：定量； - 决策树法：定量； - 德尔菲法：定性预测； - 大中取大法：不确定型决策准则，属于定性决策方法。 因此选 BC。 ---' WHERE id=4421 AND deleted=0;
UPDATE paper_question SET answer='ABC', analysis='行业环境主要分析： - 供应商； - 顾客； - 潜在竞争者； - 现有竞争者； - 替代品等。 技术环境属于一般环境，而非行业环境。 因此选 ABC。 ---' WHERE id=4422 AND deleted=0;
